(55, 'MUHAMMED SUBHI', NULL, 2, 'BUSINESS ADMINISTRATION (MBA)', '\r\n	10 years of experience in business analysts, project management and monitoring & evaluation (M&E).\r\n	7 years of experience in telecommunication project engineering. \r\n	Master in Business Administration (MBA) Certified from Gaziantep University.\r\n	Bachelor in Electronic Engineering (2003).\r\n	Project Management Professional (PMP) Certified from PMI.\r\n	Professional certificates in telecom from Huawei company in China.\r\n	Data science knowledge. \r\n	Training of trainer (TOT) certificate from the Canadian organization in Turkey.\r\n	Project Management Institute (PMI) Turkey-chapter trainer, \r\n	My trainees achieved above target in PMP exams\r\n	Project management speaker with lagility group in USA.\r\n	Helping some factories as business analyst.\r\n', 'PMP, PROJECT MANAGEMENT, BUSINESS ADMINISTRATION, Risk management, leadership', NULL, '', '+905314513232', 'soubhi28@gmail.com', '$2y$10$zfc.8GbFXJw6POXvHnD.HOVz8K6JaCTYajYSULx.AKkGC/epoC15.', NULL, 2, 1, 1, 'cv_6720dedc107ea1.71112699.pdf', 'photo_6720dedc10f8e3.62809914.JPG', '', 'Account holder: MEHMET SUBHİ ALİ\r\nBank name: Kuveyt Türk\r\nBranch: Gaziantep Şubesi\r\nAddress: Gaziantep, Türkiye\r\nAccount Number:95203430-102\r\nIBAN: TR430020500009520343000102\r\nSWIFT Code: KTEFTRIS', '2025-08-07 12:45:59', '2025-08-24 03:34:47', 1, 'male', 0, 'pending', 'Advanced', 'Advanced'),
