(145, 'SALEM NASER MUFTAH', NULL, 2, 'Business management', 'An active human resources development professional specializing in the oil and gas sector with over forty years of experience\r\nDeveloping managerial and supervisory skills', 'Human resources, education, managerial, supervisory', NULL, '', '+218913827517', 'salemelzadiy@gmail.com', '$2y$10$GS8ZQnBgNzK9uvYo0sniMeCYmyxf.Q7tG9dgKmGJhUhwKsYVUWe8q', NULL, 1, 3, 19, 'cv_69679bc9ca90f6.16306001.pdf', 'photo_69679bc9cb0cd0.00320995.jpg', '', '', '2026-01-14 06:36:09', '2026-01-14 10:18:00', 1, 'male', 0, 'pending', 'Intermediate', 'Intermediate'),
(146, 'ABD  AL JAWASH', NULL, 2, 'PETROLUM ENGINEERING', 'عملت في الشكة السورية للنفط وفي شركات اخرى كانت تعمل في سوريا(شركة توتال وشركة الفرات للنفط وشركة كونيكو ....) \r\nأعمل في مجال التدريب \r\nفي مجال إدارة العمليات وكل ما يتعلق بالإنتاج\r\nفي مجال السيفي والصحة والسلامة المهنية \r\nفي مجال إدارة العمليات والمهام الإشراقية التشغيلية\r\nالتدريب في اختصاص النيبوش والاوشا', 'OPERATIONS, SAFETY, OIL AND GAS', NULL, '', '+905397047397', 'abdaljawash@gmail.com', '$2y$10$hRxaisF5EwvXaxQpkfC73.L0IFYjoP05SF/VBvr1lNkFuoOmxanRa', NULL, 2, 1, 1, 'cv_696a2d9c93d8a3.92978099.pdf', 'photo_696a2d9c9454c3.35418918.jpg', '', '', '2026-01-16 05:22:52', '2026-01-16 05:22:52', 1, 'male', 0, 'pending', 'Advanced', 'Intermediate'),
(147, 'Mohamad Obaid', NULL, 1, 'Artificial Intelligence', 'Experienced technical trainer and academic professional specializing in artificial intelligence, data analytics, cloud computing, and project management. Proven track record in designing and delivering high-impact training programs for government entities and private sector professionals.\r\nDelivered specialized training in AI applications, Power BI and advanced analytics, Oracle Cloud Infrastructure (OCI), Microsoft Azure, Data Management in Oil & Gas, and Distributed Control Systems (DCS).\r\nStrong focus on practical, hands-on learning through real-world case studies, labs, and industry-driven scenarios. Skilled in simplifying complex technical concepts and aligning training outcomes with business needs.\r\nExperienced in developing professional training materials, including presentations, assessments, and case studies.\r\n', 'Artificial Intelligence (AI)\r\nMachine Learning (ML)\r\nData Analytics\r\nBusiness Intelligence (BI)\r\nPower BI\r\nCloud Computing\r\nOracle\r\nMicrosoft Azure\r\nData Management\r\nProject Management\r\nCyber Security\r\nData Visualization\r\nETL / Data Pipelines\r\nDashboard Development\r\nCloud Architecture\r\nDevOps Fundamentals\r\nPython (for AI & Data)\r\nIndustrial Systems (DCS)\r\nDigital Transformation\r\nAI in Business\r\nData-Driven Decision Making\r\nStrategic Planning\r\nStandards\r\nIFRS\r\nFinancial Accounting\r\nKPI\r\nAgile\r\nERP\r\nOCI\r\nSQL Server\r\nSAP\r\nFraud Detection\r\nChat Bot \r\nISO', NULL, '', '+905550331613', 'mm.obaid73@gmail.com', '$2y$10$XB3WYQpL.BcDXAK59Kocr.vC2mNItYvD5Sn0NcffcjrdFmhCupf/O', NULL, 2, 1, 1, '', 'photo_69cf8833c25fa8.25222541.jpg', '', '', '2026-04-03 03:28:19', '2026-04-03 03:28:19', 1, 'male', 0, 'pending', 'Advanced', 'Intermediate');
