INSERT INTO `orders` (`ord_id`, `ord_type_id`, `cust_id`, `ord_subject`, `ord_date`, `ord_details`, `ord_file`, `user_id`, `status`) VALUES
(6, 5, 156, 'Collaboration on Short Courses for NOC Libya', '2024-08-24', '1.	Drilling Engineering and Well Control: Emphasizing minimum cost drilling principles, this course covers mud property selection, hydraulic optimization, bit weight and rotary speed optimization, bit selection, casing design calculations, and well control methods.\r\n2.	Flow Assurance in Oil and Gas Pipelines: This course provides essential knowledge and practical skills for ensuring the safe and reliable transportation of natural gas and oil through pipelines, covering flow variable analysis, issue prediction, and pipeline performance optimization.\r\n3.	Fundamentals of Oil and Natural Gas Technology: Tailored for production and processing personnel, this course delves into oil and gas conditioning and processing unit operations, enhancing participants\' proficiency in production activities.\r\n4.	Petroleum Refining Operations: Designed to equip professionals with comprehensive knowledge and practical skills for efficient petroleum refining operations, combining theoretical learning with hands-on practice.\r\n5.	Compressors and Gas Turbines: Design and Applications: This course focuses on maximizing the reliability and performance of power generation plants and auxiliary systems through in-depth knowledge of compressor and turbine design, performance improvement techniques, and maintenance strategies.\r\n6.	Machinery Failure Analysis & Prevention: Aiming to enhance machinery reliability and prevent failures, this course covers failure mechanisms, root cause analysis, condition monitoring techniques, and reliability-centered maintenance strategies.\r\n7.	Compressors Design, Operation, and Maintenance Strategies for Power Plant\'s Gas Turbine: Participants will gain a solid understanding of compressor design, gas turbine management, and maintenance strategies, tailored to industrial applications.\r\n8.	Safety Courses: Offering a wide range of safety training modules, this course covers safe work practices, hazard identification, emergency response, and occupational health and safety management systems.\r\n9.	Safety Courses and Certificates: Participants can obtain internationally recognized safety certifications such as IOSH, NEBOSH, IIRSM, IPAF, OSHA, and specialized courses on area classifications and process safety management.\r\n10, 11 & 12. Human Resource, Leadership and Management, and Professional Secretary Training Program: This program explores the integration of Human Resource Management (HRM) practices and performance measurement within the Total Quality Management (TQM) framework, aiming to enhance the capabilities of aspiring and existing secretaries.\r\n', 'uploads/66ca30e846763_TRAINING COURSES.pdf', 6, 'new'),
(7, 1, 105, 'Marketing Skills المهارت المتقدمة في التسويق ', '2024-08-24', ' عرض تدريبي لمدة اسبوعين العدد 2 \r\nالعرض يكون له علاقة بمهارات التسويق Marketing Skills \r\n', '', 6, 'completed'),
(8, 1, 120, 'Preparing quotations ', '2024-08-29', 'Preparing 9 technical and maintenance quotations in Arabic\r\nhandled to the Requirements group in 29/8/2024\r\n\r\n-	أعمال الصيانة الميكانيكية للمعدات واستكشاف الأخطاء والأعطال التقنية في الآلات وإصلاحها وتحسين الكقاءة باستخدام الصيانة التنبؤية في مجال صيانة خطوط الانتاج بالمصانع\r\n-	التدريب على صيانة وبرمجة أنظمة التحكم المنطقي وأنظمة التشغيل الكهربائية الحديثة والآلات الدقيقة واستكشاف الأخطاء والأعطال التقنية في الآلات وإصلاحها لخطوط التصنيع وتعبئة العلب البلاستيكية وأنظمة الخلط بالمصنع\r\n-	التدريب على التشغيل الآمن وصيانة الروافع الشوكية الكهربائية والديزل وطرق متابعة اصلاحها\r\n-	التدريب على تشغيل خزانات الزيوت الأساسية والإضافات الكيميائية وأجهزة قياس الخزانات وتشغيل ومتابعة صيانة المضخات\r\n-	تشغيل ومتابعة ضواغط الهواء، تشغيل ومراقبة ومعايرة عدادات التدفق المستعملة في مصانع خلط وتعبية الزيوت\r\n-	تشغيل ومتابعة صيانة خطوط انتاج العلب البلاستيكية\r\n-	التدريب على تقنيات أنظمة التحكم في عمليات تشغيل ومتابعة وتجهيز خطوط التغليف والمنتج النهائي وعمليات جدولة الأصناف المنتجةوعلاقتها بقسم التوزيع وبحركة الأصناف المطلوبة بالسوق المحلي\r\n-	التدريب والتخطيط واستخدام البرمجيات في حركة الأصناف المطلوبة بالسوق من اليزوت المنتجةوطرق جدولة المواد التشغيلية ومراقبة المخزون\r\n-	التدريب العلمي على المنظومات التخزينية والرقابة على المخزون وإيجاد المساحات للمواد التشغيلية (زيوت / إضافات / كرتون / مواد تشغيلية)\r\n', '', 8, 'completed'),
