(67, 7, 149, 'PLAN OF 2024 WILL BE PROVIDED BY THE COMPANY ITSELF', '2024-10-12', '\r\n Overseas training plan for the year of 2024 kindly required to advise us for the following details:-\r\n1-	The Training programs schedule & its venues in Turkey (should be all scheduled before the end of the year). \r\n2-	Payment terms & condition which should be further to the execution of each program via bank transfer.\r\n\r\n', 'uploads/670a93d7d0862_training plan 2024.pdf', 6, 'completed'),
(68, 1, 109, ' مقترحات برامج تدريبية  مختلفة', '2024-10-15', 'زويدنا بمقترحات برامج تدريبية مفصلة بدوام كامل، بعناوين للمجموعات على النحو التالي/\r\n\r\nالمجموعة الاولي:\r\n\r\nالمشاركون عدد 06 مستخدمين المدة: (16) أسبوعًا (خمسة أيام في الأسبوع، خمس ساعات يوميًا).\r\n\r\nالبرامج:\r\n\r\nمهارات الادارة الحديثة عدد (01) مترشح     \r\n\r\nإدارة مكافحة الحرائق عدد (02) مترشحين    \r\n\r\nصيانة ميكانيكية متقدمة عدد (01) مترشح \r\n   \r\nالصيانة الكهربائية عدد (01) مترشح  \r\n\r\nإدارة الموارد البشرية عدد (01) مترشح   \r\n\r\nالمجموعة الثانية:\r\n\r\nالمشاركون عدد 03 مستخدمين المدة: (26) أسبوعًا (خمسة أيام في الأسبوع، خمس ساعات يوميًا).\r\n\r\nالبرامج:\r\n\r\nإدارة توثيق ومتابعة شحنات تصدير النفط عدد (01) مترشح  \r\n  \r\nإدارة سلسلة التوريد عدد (01) مترشح  \r\n \r\n(01)	مترشح Microsoft Bootcamp \r\n\r\nمع أطيب تحياتي\r\nمحمد قمو\r\nأخصائي تدريب \r\nQamu, Mohammed <MQamu@akakusoil.com>\r\n', '', 8, 'completed'),
(69, 1, 107, 'الدراسات الاقتصادية الحديثة و تقييم المشاريع', '2024-10-16', ' مطلوب\r\nمن د فراس \r\nالدراسات الاقتصادية الحديثة و تقييم المشاريع\r\nو تقنية المراجعة المالية و آليات الدفع\r\nعدد 12 في كل مجموعة\r\nلمدة اسبوعين', '', 6, 'completed'),
