(86, 1, 122, 'عدد 4 برامج مصرفية ', '2024-11-20', 'المتدربين من القطاع المصرفي \r\n\r\n1 ادارة الاىتمان \r\n2 ادارة المخاطر \r\n3 دورات مراجعه \r\n4 التدقيق الشرعي\r\n\r\n\r\nتم ارسالها الى د اسامة على الواتس في جروب الادارة\r\n\r\nمدة الدورات اسبوعين \r\n\r\nعدد المتدربين لكل دوره 10-12 متدرب ', '', 5, 'completed'),
(87, 1, 101, 'HND 2 programs', '2024-11-26', 'the High National Diploma Program for Duration 52 weeks as the following:\r\n\r\nNum.	Training Course	Number of Trainees\r\n1	HND in Mechanical Engineering	Not less than 10\r\n2	HND in Safety and Health	Not less than 10\r\n\r\n\r\n\r\n\r\nRania Diab \r\nTraining Planning Coordinator \r\n\r\nتم تحويل الموضوع الى د اسامة للنظر فيه\r\n', '', 6, 'new'),
(88, 1, 121, 'إدارة المشاريع باستخدام تكنولوجيا المعلومات والدكاء الاصطناعي', '2024-11-27', 'عنوان الورشة إدارة المشاريع باستخدام تكنولوجيا المعلومات والدكاء الاصطناعي   ابتداء من يوم 6/1/2025 لمدة خمسة أيام لعدد خمسة موظفين \r\nشركة الهروج', '', 6, 'completed'),
(89, 1, 105, 'المشاريع الهندسية ', '2024-12-02', 'مطلوب عروض فنية\r\n1- برنامج أدارة المشاريع الهندسية\r\n2- الإشراف الهندسي وأصول التنفيذ في المشاريع . \r\n\r\n لعدد ستة مشاركين \r\n المدة اسبوعين 10 ايام\r\nالمركز النوعي STC\r\nم خالد فرحات \r\nواتس ', '', 8, 'completed'),
