(91, 1, 139, 'courses in 2025.', '2024-12-13', 'NO	Course Tittle 	Duration 	Number of Participants 	Location \r\n1	Leading under  pressure	10 Days 	3	Istanbul  \r\n2	Bid Tender Management (MA43568)	10 Days 	1	Istanbul  \r\n3	International Financial Reporting Standards IFRS	10 Days 	1	Istanbul  \r\n4	Financial Modelling and Petroleum Project Eco-nomics	10 Days 	1	Istanbul \r\n5	Oil & Gas Process Utility Systems	10 Days 	1	Istanbul \r\n6	Cargo Traffic Documentation, Bill Of Lading and Its Role In Maritime Transport	10 Days 	1	Istanbul \r\n\r\n1	Leading under  pressure	10 Days 	3	Istanbul  \r\n2	Bid Tender Management (MA43568)	10 Days 	1	Istanbul  \r\n3	International Financial Reporting Standards IFRS	10 Days 	1	Istanbul  \r\n4	Financial Modelling and Petroleum Project Eco-nomics	10 Days 	1	Istanbul \r\n5	Oil & Gas Process Utility Systems	10 Days 	1	Istanbul \r\n6	Cargo Traffic Documentation, Bill Of Lading and Its Role In Maritime Transport	10 Days 	1	Istanbul \r\n', '', 8, 'new'),
(92, 1, 147, 'مجال البيئة', '2024-12-22', 'بطلب دورة تدريبية تخصصية لعدد 8 أشخاص بالإدارة في مجال البيئة (تمثل المراقبة أو تقييم الأثر البيئي، إلخ) ولمدة أسبوعين\r\n\r\nMustafa Gaja \r\nHead of Environmental Analysis Section\r\nEnvironmental Research Department\r\nPetroleum Research Center\r\nTel: +2184830022-7(2435) \r\nMobile:+218915047181 \r\nEmail: m. gaja@prclibya.com\r\n\r\n', '', 6, 'completed'),
